import{_ as t}from"./chunks/sso-login-mixed.Gf0VFA8N.js";import{_ as o}from"./chunks/sso-settings-connect.Do-2yCNv.js";import{_ as n,o as s,c as a,a3 as i}from"./chunks/framework.CchDE9cb.js";const f=JSON.parse('{"title":"How sign-in works","description":"The three ways to sign in to CapacityLens, how they stay linked to the same person, and how sessions and two-factor codes work.","frontmatter":{"title":"How sign-in works","description":"The three ways to sign in to CapacityLens, how they stay linked to the same person, and how sessions and two-factor codes work."},"headers":[],"relativePath":"company-login/index.md","filePath":"company-login/index.md","lastUpdated":null}'),r={name:"company-login/index.md"};function h(c,e,l,d,p,g){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="how-sign-in-works" tabindex="-1">How sign-in works <a class="header-anchor" href="#how-sign-in-works" aria-label="Permalink to &quot;How sign-in works&quot;">​</a></h1><p>CapacityLens supports three ways for someone to sign in: a password, a social sign-in button, or your company&#39;s own login system (single sign-on). Every installation supports at least one of these; most self-hosted installations start on passwords and move to company login later. This page explains what each mode is, how a person stays &quot;the same person&quot; no matter which one they use, and how sessions and two-factor codes work. If you&#39;re ready to set company login up, skip to <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a>; if you&#39;re moving an existing team off passwords, go to <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a>.</p><h2 id="the-three-ways-to-sign-in" tabindex="-1">The three ways to sign in <a class="header-anchor" href="#the-three-ways-to-sign-in" aria-label="Permalink to &quot;The three ways to sign in&quot;">​</a></h2><p><strong>Password.</strong> The person types an email address and password they created. On a fresh self-hosted install, the first person in signs up with a one-time setup token; everyone after that needs an invitation. This is the fastest way to start, and it&#39;s the default for a new installation.</p><p><strong>Social sign-in.</strong> A &quot;Continue with Google&quot; or &quot;Continue with Microsoft&quot; style button. These are marked <strong>experimental</strong> in CapacityLens: they work, but they&#39;re a lighter-weight option than company login and aren&#39;t accepted on installations that require company login. Treat them as a convenience for people who already have one of those accounts, not as your main door.</p><p><strong>Company login.</strong> Also called single sign-on, or SSO. The person clicks &quot;Continue with [your company]&quot; and is sent to the <a href="/capacitylens/reference/glossary">identity provider</a> your company already uses to sign people into everything else — Google Workspace, Microsoft 365, Okta, Keycloak — signs in there exactly as normal, and is sent back signed in to CapacityLens. CapacityLens never sees their password. Behind the scenes this uses a standard called OIDC (OpenID Connect), the same one almost every modern identity provider speaks.</p><p><img src="'+t+'" alt="The CapacityLens sign-in page in mixed mode, showing the email and password form above a Continue with Northwind Identity button"></p><p>Company login is the recommended mode once your team is bigger than a handful of people, because it means nobody has a CapacityLens-specific password to remember, lose, or reuse — and when someone leaves the company, disabling their account at the identity provider is most of the job done. See <a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a> to configure it.</p><h2 id="how-accounts-link-together" tabindex="-1">How accounts link together <a class="header-anchor" href="#how-accounts-link-together" aria-label="Permalink to &quot;How accounts link together&quot;">​</a></h2><p>Whichever mode someone signs in with, they&#39;re still one person: the same membership, the same role, the same allocations on the schedule. CapacityLens keeps that link by having each person <strong>prove</strong> the connection themselves, rather than guessing from an email address.</p><p>For example: Dave signed up for CapacityLens with the password <code>dave@agency.com</code>, but his company&#39;s login system knows him as <code>david.smith@agency.co.uk</code>. CapacityLens won&#39;t silently treat those as the same person just because they sound alike. Instead, Dave signs in with his password as usual, goes to Settings, and clicks <strong>Connect</strong> next to company login. He&#39;s sent to that login system, signs in there, and comes back — and only then are the two identities linked. From that point on, CapacityLens remembers him by a stable ID the login system issues (not by his email address), so even if his email changes again later, the link holds.</p><p><img src="'+o+'" alt="The Company sign-in card in Settings, explaining that the organisation is moving to Northwind Identity sign-in, with a Connect Northwind Identity button"></p><p>The one rule that can&#39;t be skipped: at the moment someone connects, the email their login system reports has to be <strong>identical</strong> to their CapacityLens email. If it isn&#39;t, an Owner or Admin can correct the CapacityLens side to match — see <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a> for that repair step. Nobody has to change anything on the login system&#39;s side.</p><h2 id="sessions-and-staying-signed-in" tabindex="-1">Sessions and staying signed in <a class="header-anchor" href="#sessions-and-staying-signed-in" aria-label="Permalink to &quot;Sessions and staying signed in&quot;">​</a></h2><p>A CapacityLens session lasts at most twelve hours from the moment someone signs in, and doesn&#39;t renew itself just because they&#39;re active — after twelve hours, they sign in again regardless. Separately, thirty minutes with no activity also signs someone out.</p><p>A handful of sensitive actions — changing a password, resetting someone else&#39;s password, removing a member, exporting data, deleting a company — need a session that&#39;s &quot;fresh&quot;: if it&#39;s been more than fifteen minutes since the person last proved who they are, CapacityLens asks them to confirm again (their password, or a two-factor code) before letting the action through. This doesn&#39;t sign them out or lose their place; it&#39;s a quick check in place.</p><h2 id="extra-security-two-factor-sign-in" tabindex="-1">Extra security: two-factor sign-in <a class="header-anchor" href="#extra-security-two-factor-sign-in" aria-label="Permalink to &quot;Extra security: two-factor sign-in&quot;">​</a></h2><p>In password mode, an Owner or Admin can require everyone to enroll in two-factor sign-in — <a href="/capacitylens/reference/glossary">TOTP</a>, the six-digit code from an authenticator app that changes every thirty seconds. Once required, a new person has to finish enrolling before they can see any company data. Enrolling also gives them one-time recovery codes to use if they lose their authenticator; five wrong codes in a row locks the account for fifteen minutes.</p><p>There&#39;s deliberately no administrator override for lost two-factor codes: if someone loses both their authenticator and their recovery codes, getting them back in requires the person who runs the server, not a button in the product. This is covered in the self-hosting documentation.</p><p>Company login sidesteps this entirely — CapacityLens treats every company-login session as already meeting its two-factor requirement, because your identity provider is responsible for its own sign-in policy (including whether it requires two-factor codes). If your identity provider doesn&#39;t enforce two-factor sign-in, turning it on there gives your team the same protection.</p><h2 id="which-mode-is-right-for-you" tabindex="-1">Which mode is right for you <a class="header-anchor" href="#which-mode-is-right-for-you" aria-label="Permalink to &quot;Which mode is right for you&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Recommended mode</th></tr></thead><tbody><tr><td>Trying CapacityLens out, or a very small trusted team</td><td>Password, or <a href="/capacitylens/getting-started/try-the-demo">the demo</a> with no sign-in at all</td></tr><tr><td>A self-hosted team without a shared identity provider</td><td>Password, with two-factor sign-in required</td></tr><tr><td>A team that already signs into Google, Microsoft, Okta or Keycloak for everything else</td><td><a href="/capacitylens/company-login/set-up-company-login">Company login</a></td></tr><tr><td>An existing password team that wants to move to company login without locking anyone out</td><td>Run both at once first — see <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a></td></tr></tbody></table><p>Self-hosted installations can run password-only, company-login-only, or both at once (useful for keeping contractors on passwords while staff use company login). Whichever you choose is a setting on your own server — see <a href="/capacitylens/self-hosting/configuration">Configuration</a> for the full list of options.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/company-login/set-up-company-login">Set up your company login</a> to connect CapacityLens to Google, Microsoft, Okta or Keycloak, or <a href="/capacitylens/company-login/move-to-single-sign-on">Move from passwords to single sign-on</a> if you already have a password team.</p>',25)])])}const w=n(r,[["render",h]]);export{f as __pageData,w as default};
